import React, { useEffect, useState } from "react";
import { Plus, Minus, Flame, Salad, Sandwich, Soup, Citrus } from "lucide-react";
import DishArt from "../components/DishArt";
import { api } from "../api/client";
import { useCart } from "../context/CartContext";

const currency = (n) => `₹${n.toFixed(0)}`;

const CATEGORIES = [
  { id: "Bowls", label: "Curry Bowls", icon: Salad },
  { id: "Wraps", label: "Rolls", icon: Sandwich },
  { id: "Soups", label: "Soups", icon: Soup },
  { id: "Smoothies", label: "Lassi & Chaas", icon: Citrus },
];

export default function Menu() {
  const [activeCat, setActiveCat] = useState("Bowls");
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const { items: cart, add, remove } = useCart();

  useEffect(() => {
    setLoading(true);
    setError("");
    api
      .getMenu({ category: activeCat })
      .then(setItems)
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, [activeCat]);

  return (
    <main className="container" style={{ padding: "44px 24px 80px" }}>
      <h1 className="disp" style={{ fontSize: 34, fontWeight: 700, color: "var(--forest-dark)" }}>
        The menu
      </h1>
      <p style={{ color: "var(--ink-soft)", marginTop: 4, fontSize: 15 }}>Sourced this morning, cooked to order.</p>

      <div style={{ display: "flex", gap: 10, marginTop: 26, marginBottom: 30, flexWrap: "wrap" }}>
        {CATEGORIES.map((c) => {
          const Icon = c.icon;
          const active = activeCat === c.id;
          return (
            <button
              key={c.id}
              onClick={() => setActiveCat(c.id)}
              className="focus-ring"
              style={{
                display: "flex",
                alignItems: "center",
                gap: 8,
                padding: "10px 18px",
                borderRadius: 999,
                border: active ? "1px solid var(--forest)" : "1px solid var(--border)",
                background: active ? "var(--forest)" : "#FFFFFF",
                color: active ? "#FAFAFA" : "#4F4F4F",
                fontWeight: 700,
                fontSize: 14,
              }}
            >
              <Icon size={16} /> {c.label}
            </button>
          );
        })}
      </div>

      {loading && <div style={{ color: "var(--ink-faint)" }}>Loading menu…</div>}

      {error && (
        <div style={{ background: "#FBEAD8", border: "1px solid rgba(217,96,60,0.3)", color: "var(--tomato)", borderRadius: 14, padding: 16, fontSize: 14 }}>
          Couldn't load the menu ({error}). Make sure the backend API is running on the URL set in
          <code> VITE_API_URL</code> and that <code>npm run seed</code> has been run.
        </div>
      )}

      {!loading && !error && items.length === 0 && (
        <div style={{ color: "var(--ink-faint)" }}>No items in this category yet.</div>
      )}

      {!loading && !error && (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 20 }}>
          {items.map((item, idx) => {
            const qty = cart[item._id]?.qty || 0;
            return (
              <div key={item._id} style={{ background: "#FFFFFF", borderRadius: 12, overflow: "hidden", border: "1px solid var(--border)", display: "flex", flexDirection: "column", boxShadow: "0 1px 3px rgba(0,0,0,0.04)" }}>
                <div style={{ position: "relative" }}>
                  <DishArt seed={idx} />
                  <div
                    className="mono"
                    style={{
                      position: "absolute",
                      top: 10,
                      left: 10,
                      background: "var(--curry)",
                      color: "#FFFFFF",
                      borderRadius: 6,
                      padding: "3px 7px",
                      fontSize: 12,
                      display: "flex",
                      alignItems: "center",
                      gap: 4,
                    }}
                  >
                    ★ 4.{3 + (idx % 6)}
                  </div>
                </div>
                <div style={{ padding: 16, display: "flex", flexDirection: "column", flex: 1 }}>
                <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                  {item.tags?.[0] && (
                    <span style={{ fontSize: 11, fontWeight: 800, color: "var(--turmeric)", letterSpacing: "0.04em" }}>
                      {item.tags[0].toUpperCase()}
                    </span>
                  )}
                  <span style={{ fontSize: 11, color: "var(--ink-faint)", display: "flex", alignItems: "center", gap: 3 }}>
                    <Flame size={11} /> {item.calories} kcal
                  </span>
                </div>
                <div className="disp" style={{ fontSize: 16, fontWeight: 600, color: "var(--ink)", marginTop: 6 }}>
                  {item.name}
                </div>
                <div style={{ fontSize: 13.5, color: "var(--ink-faint)", marginTop: 4, flex: 1 }}>{item.description}</div>
                <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 14 }}>
                  <span className="mono" style={{ fontWeight: 700, color: "var(--ink)", fontSize: 16 }}>{currency(item.price)}</span>
                  {qty === 0 ? (
                    <button
                      onClick={() => add(item)}
                      className="focus-ring"
                      style={{ background: "var(--forest)", color: "#FFFFFF", border: "none", borderRadius: 999, padding: "9px 16px", fontWeight: 700, fontSize: 13.5, display: "flex", alignItems: "center", gap: 6 }}
                    >
                      <Plus size={14} /> Add
                    </button>
                  ) : (
                    <div style={{ display: "flex", alignItems: "center", gap: 10, background: "var(--bg)", borderRadius: 999, padding: "4px 6px" }}>
                      <button onClick={() => remove(item._id)} className="focus-ring" style={{ background: "#FFFFFF", border: "1px solid var(--border)", borderRadius: "50%", width: 26, height: 26, display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <Minus size={13} color="var(--forest)" />
                      </button>
                      <span style={{ fontWeight: 800, minWidth: 14, textAlign: "center" }}>{qty}</span>
                      <button onClick={() => add(item)} className="focus-ring" style={{ background: "var(--forest)", border: "none", borderRadius: "50%", width: 26, height: 26, display: "flex", alignItems: "center", justifyContent: "center" }}>
                        <Plus size={13} color="#FFFFFF" />
                      </button>
                    </div>
                  )}
                </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </main>
  );
}
